function processTransaction(balance, amount, type) {
  if (type === "WITHDRAW") {
    if (amount <= 0) {
      return { success: false, error: "Invalid amount" };
    }
    if (amount > balance) {
      return { success: false, error: "Insufficient funds" };
    }
    return { success: true, newBalance: balance - amount };
  } else if (type === "DEPOSIT") {
    if (amount <= 0) {
      return { success: false, error: "Invalid deposit amount" };
    }
    return { success: true, newBalance: balance + amount };
  }
  return { success: false, error: "Unknown transaction type" };
}
console.log(processTransaction(100, 40, "WITHDRAW")); // { success: true, newBalance: 60 }

function fibMemo(n, memo = {}) {
  if (n in memo) return memo[n];
  if (n <= 1) return n;
  memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  return memo[n];
}
console.log(fibMemo(50)); // Returns 12586269025 O(N) runtime instead of exponential O(2^N)

