    struct ASTNode* right; // Node representing '5'
};

const BASE62 = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
function encodeIdToBase62(num) {
  let chars = [];
  while (num > 0) {
    chars.push(BASE62[num % 62]);
    num = Math.floor(num / 62);
  }
  return chars.reverse().join('');
}
console.log(encodeIdToBase62(9999999)); // "b5A9" - compact short URL path
